IP=$(az vm list -g resume-builder --query "[0].name" -o tsv)PublicIP && ( az network public-ip update -g resume-builder -n $IP --dns-name reesume-app -o none --only-show-errors || az network public-ip update -g resume-builder -n $IP --dns-name reesume-app-$RANDOM -o none --only-show-errors ) && echo "===== YOUR FREE ADDRESS =====" && az network public-ip show -g resume-builder -n $IP --query dnsSettings.fqdn -o tsv
